// --- helpers ---------------------------------------------------------------

// objectSchema infers the base object JSON Schema for a tool input struct via
// the SDK's reflection (the same inference the SDK would run for a nil input
// schema), so nested object/array params keep their structural shape; callers
// then override the required list and any enum properties. It panics on an
// un-inferrable type — a build-time contract error surfaced at server start.
func objectSchema[T any]() *jsonschema.Schema {
	s, err := jsonschema.For[T](nil)
	if err != nil {
		panic(fmt.Sprintf("mcp input schema inference: %v", err))
	}
	if s.Properties == nil {
		s.Properties = map[string]*jsonschema.Schema{}
	}
	return s
}

// fixUUIDStrings walks an inferred schema and retypes every uuid.UUID ([16]byte)
// property from the SDK's structural inference (an array of 16 0-255 bytes) to
// the schema the value actually marshals as on the wire: a string in RFC 4122
// form. It MUST run before relaxRawJSON, which would otherwise blank the same
// node as an indistinguishable raw-byte-array signature (T11 finding).
func fixUUIDStrings(s *jsonschema.Schema) {
	if s == nil {
		return
	}
	if isUUIDArray(s) {
		*s = jsonschema.Schema{Type: "string", Format: "uuid"}
		return
	}
	for _, p := range s.Properties {
		fixUUIDStrings(p)
	}
	fixUUIDStrings(s.Items)
	fixUUIDStrings(s.AdditionalProperties)
	for _, p := range s.PrefixItems {
		fixUUIDStrings(p)
	}
}

// isUUIDArray reports whether a schema is the jsonschema-go signature of a Go
// uuid.UUID ([16]byte): the same raw-byte-array shape as isRawByteArray, further
// narrowed to exactly 16 items (a fixed-size array), which is unique to UUIDs
// among this codebase's byte-carrier fields.
func isUUIDArray(s *jsonschema.Schema) bool {
	if !isRawByteArray(s) {
		return false
	}
	return s.MinItems != nil && *s.MinItems == 16 && s.MaxItems != nil && *s.MaxItems == 16
}

// relaxRawJSON walks an inferred schema and relaxes every json.RawMessage /
// []byte JSON-carrier property to a permissive (accept-anything) schema. The SDK
// infers such a Go field as an array of 0-255 bytes, which rejects the real JSON
// object/string the manager actually emits or accepts (QA finding F26); the rest
// of the inferred shape is preserved. The permissive schema carries a
// Description so it marshals as a JSON OBJECT (`{"description":...}`) rather
// than the zero-value Schema{}, which the library marshals as bare JSON `true`
// — valid JSON Schema, but rejected by the TS MCP SDK's Zod validator, which
// requires every property schema to be an object (T11 finding).
func relaxRawJSON(s *jsonschema.Schema) {
	if s == nil {
		return
	}
	if isRawByteArray(s) {
		*s = jsonschema.Schema{Description: "any JSON value"}
		return
	}
	for _, p := range s.Properties {
		relaxRawJSON(p)
	}
	relaxRawJSON(s.Items)
	relaxRawJSON(s.AdditionalProperties)
	for _, p := range s.PrefixItems {
		relaxRawJSON(p)
	}
}

// isRawByteArray reports whether a schema is the jsonschema-go signature of a Go
// []byte / json.RawMessage: an array (possibly nullable) whose items are bytes
// (integer, 0..255).
func isRawByteArray(s *jsonschema.Schema) bool {
	isArray := s.Type == "array"
	for _, t := range s.Types {
		if t == "array" {
			isArray = true
		}
	}
	if !isArray || s.Items == nil {
		return false
	}
	it := s.Items
	if it.Type != "integer" {
		return false
	}
	return it.Minimum != nil && *it.Minimum == 0 && it.Maximum != nil && *it.Maximum == 255
}

// allowNullMaps walks an inferred schema and unions "null" into every Go-map
// node's type. jsonschema-go infers a Go map as a bare {type:"object"}, but a
// nil map marshals to JSON null (unlike a nil slice, which the library already
// types as ["null","array"]). Read models legitimately emit nil maps in early
// project phases (e.g. ProjectState.ActivityConstruction before construction),
// so the honest schema must accept null there — otherwise the SDK's output
// validation rejects a payload the HTTP surface serves fine (QA finding F29).
func allowNullMaps(s *jsonschema.Schema) {
	if s == nil {
		return
	}
	if isMapNode(s) {
		s.Types = []string{"null", "object"}
		s.Type = ""
	}
	for _, p := range s.Properties {
		allowNullMaps(p)
	}
	allowNullMaps(s.Items)
	allowNullMaps(s.AdditionalProperties)
	for _, p := range s.PrefixItems {
		allowNullMaps(p)
	}
}

// isMapNode reports whether a schema node is jsonschema-go's inference of a Go
// map: an object node carrying an additionalProperties element schema. A struct
// is also typed "object" but sets additionalProperties to the false schema
// (Not set), which this distinguishes so struct nodes are never made nullable.
func isMapNode(s *jsonschema.Schema) bool {
	isObject := s.Type == "object"
	for _, t := range s.Types {
		if t == "object" {
			isObject = true
		}
	}
	ap := s.AdditionalProperties
	return isObject && ap != nil && ap.Not == nil
}

func mapManagerError(err error) error {
	var me *fwmanager.Error
	if errors.As(err, &me) {
		return fmt.Errorf("%s: %s", me.Kind.String(), me.Detail)
	}
	return err
}
